WITH with_prev AS (SELECT *, LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at, id) AS prev_started_at FROM sessions), gaps AS (SELECT *, CASE WHEN prev_started_at IS NULL OR started_at > prev_started_at + INTERVAL '30' DAY THEN 1 ELSE 0 END AS is_new_burst FROM with_prev), islands AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM gaps) SELECT id, started_at, country, prev_started_at, is_new_burst, island_id FROM islands ORDER BY id NULLS FIRST, island_id
